package main

import (
	"bufio"
	"encoding/base64"
	"encoding/binary"
	"fmt"
	"math"
	"os"
	"sort"
)

// =========================================================================
// PASTE THE HALVED BASE64 STRING GENERATED BY PACK.GO HERE:
// =========================================================================
const CompressedWeights = ""

const (
	BoardSize   = 9
	NumCells    = BoardSize * BoardSize
	NumFilters  = 8
	TotalParam  = (NumFilters * 3 * 3) + NumFilters + (NumFilters * 3 * 3 * NumFilters) + NumFilters + (1 * 1 * NumFilters) + 1
	TargetScore = 5
)

type ScoredMove struct {
	Idx   int
	Logit float64
}

// Unpacks halved float32 binary weights from Base64 directly into float64 engine layers
func DecodeWeights(encoded string) []float64 {
	data, err := base64.StdEncoding.DecodeString(encoded)
	if err != nil || len(data) != TotalParam*4 { // Strictly checks float32 bounds (4 bytes per parameter)
		return make([]float64, TotalParam)
	}

	weights := make([]float64, TotalParam)
	for i := 0; i < TotalParam; i++ {
		bits32 := binary.LittleEndian.Uint32(data[i*4 : (i+1)*4])
		weights[i] = float64(math.Float32frombits(bits32))
	}
	return weights
}

// =========================================================================
// ATARI-GO RULES SIMULATOR
// =========================================================================
func getLiberties(board []int, startIdx int, color int, visited []bool, group *[]int) int {
	if visited[startIdx] {
		return 0
	}
	visited[startIdx] = true
	*group = append(*group, startIdx)

	liberties := 0
	x, y := startIdx/BoardSize, startIdx%BoardSize
	dx := []int{-1, 1, 0, 0}
	dy := []int{0, 0, -1, 1}

	for i := 0; i < 4; i++ {
		nx, ny := x+dx[i], y+dy[i]
		if nx >= 0 && nx < BoardSize && ny >= 0 && ny < BoardSize {
			nIdx := nx*BoardSize + ny
			if board[nIdx] == 0 {
				if !visited[nIdx] {
					liberties++
					visited[nIdx] = true
				}
			} else if board[nIdx] == color && !visited[nIdx] {
				liberties += getLiberties(board, nIdx, color, visited, group)
			}
		}
	}
	for i := 0; i < 4; i++ {
		nx, ny := x+dx[i], y+dy[i]
		if nx >= 0 && nx < BoardSize && ny >= 0 && ny < BoardSize {
			nIdx := nx*BoardSize + ny
			if board[nIdx] == 0 {
				visited[nIdx] = false
			}
		}
	}
	return liberties
}

func CheckMoveAndCapture(currentBoard []int, moveIdx int, color int) ([]int, int, bool) {
	if currentBoard[moveIdx] != 0 {
		return nil, 0, false
	}

	nextBoard := make([]int, NumCells)
	copy(nextBoard, currentBoard)
	nextBoard[moveIdx] = color

	opponent := -color
	capturedStones := 0
	visited := make([]bool, NumCells)

	for i := 0; i < NumCells; i++ {
		if nextBoard[i] == opponent && !visited[i] {
			var group []int
			if getLiberties(nextBoard, i, opponent, visited, &group) == 0 {
				capturedStones += len(group)
				for _, idx := range group {
					nextBoard[idx] = 0
				}
			}
		}
	}

	if capturedStones == 0 {
		visitedSelf := make([]bool, NumCells)
		var groupSelf []int
		if getLiberties(nextBoard, moveIdx, color, visitedSelf, &groupSelf) == 0 {
			return nil, 0, false
		}
	}
	return nextBoard, capturedStones, true
}

// =========================================================================
// NEURAL NETWORK FORWARD PASS (CNN)
// =========================================================================
func ForwardCNN(weights []float64, board []float64) []float64 {
	w1Start := 0
	w1End := NumFilters * 3 * 3
	b1Start := w1End
	b1End := b1Start + NumFilters
	w2Start := b1End
	w2End := w2Start + (NumFilters * 3 * 3 * NumFilters)
	b2Start := w2End
	b2End := b2Start + NumFilters
	w3Start := b2End
	w3End := w3Start + NumFilters
	b3Idx := w3End

	fMaps1 := make([]float64, BoardSize*BoardSize*NumFilters)
	for f := 0; f < NumFilters; f++ {
		fIdx := f * NumCells
		wIdx := w1Start + f*9
		bias := weights[b1Start+f]
		for r := 0; r < BoardSize; r++ {
			for c := 0; c < BoardSize; c++ {
				sum := bias
				for ky := -1; ky <= 1; ky++ {
					for kx := -1; kx <= 1; kx++ {
						nr, nc := r+ky, c+kx
						if nr >= 0 && nr < BoardSize && nc >= 0 && nc < BoardSize {
							sum += board[nr*BoardSize+nc] * weights[wIdx+(ky+1)*3+(kx+1)]
						}
					}
				}
				if sum < 0 {
					sum *= 0.01
				}
				fMaps1[fIdx+r*BoardSize+c] = sum
			}
		}
	}

	fMaps2 := make([]float64, BoardSize*BoardSize*NumFilters)
	for fOut := 0; fOut < NumFilters; fOut++ {
		fOutIdx := fOut * NumCells
		bias := weights[b2Start+fOut]
		for r := 0; r < BoardSize; r++ {
			for c := 0; c < BoardSize; c++ {
				sum := bias
				for ky := -1; ky <= 1; ky++ {
					for kx := -1; kx <= 1; kx++ {
						nr, nc := r+ky, c+kx
						if nr >= 0 && nr < BoardSize && nc >= 0 && nc < BoardSize {
							for fIn := 0; fIn < NumFilters; fIn++ {
								wIdx := w2Start + (fOut*NumFilters+fIn)*9
								sum += fMaps1[fIn*NumCells+nr*BoardSize+nc] * weights[wIdx+(ky+1)*3+(kx+1)]
							}
						}
					}
				}
				if sum < 0 {
					sum *= 0.01
				}
				fMaps2[fOutIdx+r*BoardSize+c] = sum
			}
		}
	}

	output := make([]float64, NumCells)
	finalBias := weights[b3Idx]
	for i := 0; i < NumCells; i++ {
		sum := finalBias
		for f := 0; f < NumFilters; f++ {
			sum += fMaps2[f*NumCells+i] * weights[w3Start+f]
		}
		output[i] = sum
	}
	return output
}

// =========================================================================
// HYBRID MINIMAX STRATEGY (STONE SCORES ONLY)
// =========================================================================
func evaluateHybridPosition(logits []float64, board []int, aiColor int, aiScore, humanScore int) float64 {
	if aiScore >= TargetScore {
		return 15000.0
	}
	if humanScore >= TargetScore {
		return -15000.0
	}
	cnnBonus := 0.0
	for i := 0; i < NumCells; i++ {
		if board[i] == aiColor {
			cnnBonus += logits[i]
		}
	}
	return float64(aiScore)*500.0 - float64(humanScore)*1000.0 + cnnBonus*0.5
}

func hybridAlphaBeta(logits []float64, board []int, depth int, alpha, beta float64, isMax bool, aiColor, color, aiScore, humanScore int) float64 {
	if depth == 0 {
		return evaluateHybridPosition(logits, board, aiColor, aiScore, humanScore)
	}
	var validMoves []int
	for i := 0; i < NumCells; i++ {
		if board[i] == 0 {
			_, _, legal := CheckMoveAndCapture(board, i, color)
			if legal {
				validMoves = append(validMoves, i)
			}
		}
	}
	if len(validMoves) == 0 {
		return evaluateHybridPosition(logits, board, aiColor, aiScore, humanScore)
	}

	if isMax {
		maxEval := -math.MaxFloat64
		for _, move := range validMoves {
			nextBoard, capCount, _ := CheckMoveAndCapture(board, move, color)
			newAiScore := aiScore
			if color == aiColor {
				newAiScore += capCount
			}
			eval := hybridAlphaBeta(logits, nextBoard, depth-1, alpha, beta, false, aiColor, -color, newAiScore, humanScore)
			if eval > maxEval {
				maxEval = eval
			}
			if eval > alpha {
				alpha = eval
			}
			if beta <= alpha {
				break
			}
		}
		return maxEval
	} else {
		minEval := math.MaxFloat64
		for _, move := range validMoves {
			nextBoard, capCount, _ := CheckMoveAndCapture(board, move, color)
			newHumanScore := humanScore
			if color != aiColor {
				newHumanScore += capCount
			}
			eval := hybridAlphaBeta(logits, nextBoard, depth-1, alpha, beta, true, aiColor, -color, aiScore, newHumanScore)
			if eval < minEval {
				minEval = eval
			}
			if eval < beta {
				beta = eval
			}
			if beta <= alpha {
				break
			}
		}
		return minEval
	}
}

func GetHybridMove(weights []float64, board []int, color int, aiScore, humanScore int) (int, int) {
	netInput := make([]float64, NumCells)
	for i := 0; i < NumCells; i++ {
		netInput[i] = float64(board[i] * color)
	}
	logits := ForwardCNN(weights, netInput)

	var candidates []ScoredMove
	for i := 0; i < NumCells; i++ {
		if board[i] == 0 {
			_, capCount, legal := CheckMoveAndCapture(board, i, color)
			if legal {
				if aiScore+capCount >= TargetScore {
					return i, capCount
				}
				candidates = append(candidates, ScoredMove{Idx: i, Logit: logits[i] + float64(capCount)*50.0})
			}
		}
	}
	if len(candidates) == 0 {
		return -1, 0
	}

	sort.Slice(candidates, func(i, j int) bool { return candidates[i].Logit > candidates[j].Logit })
	limit := 15
	if len(candidates) < limit {
		limit = len(candidates)
	}
	bestCandidates := candidates[:limit]

	bestMove := -1
	bestValue := -math.MaxFloat64
	alpha := -math.MaxFloat64
	beta := math.MaxFloat64

	for _, cand := range bestCandidates {
		nextBoard, capCount, _ := CheckMoveAndCapture(board, cand.Idx, color)
		boardValue := hybridAlphaBeta(logits, nextBoard, 2, alpha, beta, false, color, -color, aiScore+capCount, humanScore)
		if boardValue > bestValue {
			bestValue = boardValue
			bestMove = cand.Idx
		}
		if boardValue > alpha {
			alpha = boardValue
		}
	}
	if bestMove == -1 {
		bestMove = bestCandidates[0].Idx
	}
	_, finalCap, _ := CheckMoveAndCapture(board, bestMove, color)
	return bestMove, finalCap
}

// =========================================================================
// CODINGAME STANDARD STANDARD I/O COMPLIANCE
// =========================================================================
func main() {
	weights := DecodeWeights(CompressedWeights)
	scanner := bufio.NewScanner(os.Stdin)

	scanner.Scan()
	myColorStr := scanner.Text()
	myColor := 1
	if myColorStr == "WHITE" {
		myColor = -1
	}

	var boardSize int
	scanner.Scan()
	fmt.Sscan(scanner.Text(), &boardSize)

	for {
		var opponentX, opponentY int
		scanner.Scan()
		fmt.Sscan(scanner.Text(), &opponentX, &opponentY)

		var myScore, opponentScore int
		scanner.Scan()
		fmt.Sscan(scanner.Text(), &myScore, &opponentScore)

		board := make([]int, NumCells)
		for y := 0; y < boardSize; y++ {
			scanner.Scan()
			line := scanner.Text()
			for x := 0; x < boardSize; x++ {
				idx := y*BoardSize + x
				if line[x] == 'B' {
					board[idx] = 1
				} else if line[x] == 'W' {
					board[idx] = -1
				} else {
					board[idx] = 0
				}
			}
		}

		bestMove, _ := GetHybridMove(weights, board, myColor, myScore, opponentScore)

		if bestMove == -1 {
			fmt.Println("PASS")
		} else {
			fmt.Printf("%d %d\n", bestMove%BoardSize, bestMove/BoardSize)
		}
	}
}
